import{_ as a,o as e,c as n,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"CAP / PACELC / BASE","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/concepts/cap.md","filePath":"distributed/concepts/cap.md","lastUpdated":1788475713000}'),r={name:"distributed/concepts/cap.md"};function o(i,t,l,d,c,p){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="cap-pacelc-base" tabindex="-1">CAP / PACELC / BASE <a class="header-anchor" href="#cap-pacelc-base" aria-label="Permalink to &quot;CAP / PACELC / BASE&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>CAP 定理 (Brewer 2000 假说、Gilbert-Lynch 2002 证明): 异步网络下，分布式系统在 Consistency (C, 线性化)、Availability (A, 每个请求最终响应)、Partition-tolerance (P, 容忍消息丢失) 三者中<strong>最多满足两个</strong>。由于真实网络必分区 (P 必选)，实际选择是 <strong>CP vs AP</strong>。PACELC (Abadi 2010) 进一步补充: 即使无分区时也需在 Latency vs Consistency 间权衡——给完整取舍空间。BASE (Basically Available + Soft State + Eventually Consistent) 是 ACID 反面、AP 系统的设计风格。这章的目标是区分<strong>理论形式化</strong> (CAP 是定义严格的定理)、<strong>工程实践</strong> (CAP 是开发者口中的&quot;标签&quot;)、<strong>常见误读</strong> (&quot;CP 永远不可用&quot;、&quot;AP 永远不准&quot;)。</p><hr><h2 id="一、cap-形式化-gilbert-lynch-2002" tabindex="-1">一、CAP 形式化 (Gilbert-Lynch 2002) <a class="header-anchor" href="#一、cap-形式化-gilbert-lynch-2002" aria-label="Permalink to &quot;一、CAP 形式化 (Gilbert-Lynch 2002)&quot;">​</a></h2><h3 id="三性质的定义" tabindex="-1">三性质的定义 <a class="header-anchor" href="#三性质的定义" aria-label="Permalink to &quot;三性质的定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>性质</th><th>形式化定义</th></tr></thead><tbody><tr><td>Consistency</td><td>线性化 (linearizability) : 所有操作看上去都在某个<em>全局实时顺序</em>上原子完成, 任何 read 返回最近一次 write 的值</td></tr><tr><td>Availability</td><td>每个对<strong>非故障节点</strong>的请求最终<strong>收到非错误响应</strong> (无超时限制)</td></tr><tr><td>Partition tolerance</td><td>网络可能丢失任意数量消息 (一对节点间任意方向丢包), 系统仍工作</td></tr></tbody></table><p>定理: 这三者<strong>不能同时</strong>满足。证明核心: 一个 system 假设满足三者, 考虑两节点 A 和 B 被网络分区、客户端向 A 写 &quot;x=1&quot;、向 B 读 x——A 必须响应 (availability), 但 B 不能与 A 同步 (partition), 于是 B 返回旧值——违反 consistency。</p><h3 id="关键细节-异步网络-总能完成" tabindex="-1">关键细节: 异步网络 + 总能完成 <a class="header-anchor" href="#关键细节-异步网络-总能完成" aria-label="Permalink to &quot;关键细节: 异步网络 + 总能完成&quot;">​</a></h3><p>证明依赖<strong>异步网络</strong> (消息延迟无上限) + <strong>总能完成</strong> (liveness 强定义)。若系统允许在分区时<strong>无限封住</strong>请求直到分区恢复 (即 不严格保证 availability, 只 guarantee eventual), 那 CP 就成立——etcd / ZooKeeper 实际是这种&quot;partition 时 best-effort block&quot;。</p><h3 id="consistency-等级" tabindex="-1">Consistency 等级 <a class="header-anchor" href="#consistency-等级" aria-label="Permalink to &quot;Consistency 等级&quot;">​</a></h3><p>CAP 中 C 严格指 <strong>线性化</strong> (Linearizability), 是<strong>最强</strong>形式一致。更弱:</p><ol><li><strong>Linearizability</strong>: 单对象强一致。</li><li><strong>Sequential Consistency</strong> (Lamport 1979): 所有进程看到的操作序列<strong>全局同一序</strong>, 但不要求与 real-time 一致。</li><li><strong>Causal Consistency</strong>: 有 causality 关系的操作各进程看到的序一致; 无 causality 的并发操作可不同序。</li><li><strong>Eventual Consistency</strong>: 给足时间无新写入时所有副本会收敛。</li></ol><p>CAP 中的 C 严格只指 1。现代系统如 Spanner 是 Linearizable, Dynamo 是 Eventual, MongoDB 是 Sequential (默认), Cassandra 是可调 ( LOCAL_QUOURM → 介于, CL=ALL → linearizable)。</p><hr><h2 id="二、cp-vs-ap-实例" tabindex="-1">二、CP vs AP 实例 <a class="header-anchor" href="#二、cp-vs-ap-实例" aria-label="Permalink to &quot;二、CP vs AP 实例&quot;">​</a></h2><h3 id="cp-系统" tabindex="-1">CP 系统 <a class="header-anchor" href="#cp-系统" aria-label="Permalink to &quot;CP 系统&quot;">​</a></h3><p>分区时<strong>拒绝服务</strong>保证 consistency:</p><ul><li><strong>etcd</strong>: Raft + WAL persistent。Quorum 不可达时写入阻塞。</li><li><strong>ZooKeeper</strong>: ZAB (Paxos 变种) + 5 节点 quorum。Leader 仅一个, leader died 重新 elect ~200ms, 期间不可写。</li><li><strong>HBase</strong>: HMaster 单点 + RegionServer副本 backed by HDFS NameNode (单点 HA via QJM)。强一致 but 单点 fail-stop.</li><li><strong>Spanner</strong>: TrueTime + Paxos groups。TrueTime 不确定窗口期间 commit wait, 保证 external consistency。</li></ul><p>几乎所有 CP 系统并不是&quot;分区时 unavailable&quot;——只是&quot;分区时<strong>降低可用性</strong>&quot;——决策都是&quot;是否抛弃本次请求&quot;。</p><h3 id="ap-系统" tabindex="-1">AP 系统 <a class="header-anchor" href="#ap-系统" aria-label="Permalink to &quot;AP 系统&quot;">​</a></h3><p>分区时<strong>继续服务</strong>保证 availability, 用 eventual consistency 收敛:</p><ul><li><strong>Cassandra</strong>: Dynamo 架构, W+R 可调一致性。Quorum 不可达也可降级写。读到的可能 stale (但 eventually converges)。</li><li><strong>DynamoDB</strong>: AWS Dynamo 论文基础, Eventually consistent reads 是默认, 但 2018 起支持强一致 read (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo>=</mo><mi>W</mi><mo>+</mo><mn>1</mn><mo>=</mo><mi>N</mi></mrow><annotation encoding="application/x-tex">R=W+1=N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 在最新副本).</li><li><strong>Riak</strong>: Vector Clock + hint handoff + active repair。</li><li><strong>CouchDB</strong>: Multi-master + MVCC。</li></ul><p>AP 系统<strong>关键</strong>的代价: 用户可能读到 stale data。需要业务层<strong>接受这窗口</strong>——Twitter timeline、Amazon shopping cart acceptable, 银行账户一般 not。</p><h3 id="工程实现的-nuanced-ca-真的存在吗" tabindex="-1">工程实现的 nuanced: CA 真的存在吗? <a class="header-anchor" href="#工程实现的-nuanced-ca-真的存在吗" aria-label="Permalink to &quot;工程实现的 nuanced: CA 真的存在吗?&quot;">​</a></h3><p>理论上: <strong>CA 系统 = 单机</strong>。在单进程数据库 (PostgreSQL 运行在一台机), 无网络分区概念。一旦跨网络或跨物理机, 就有分区风险, 就必须<strong>容忍 P</strong>——即放弃 CA。生产中常说 &quot;CA 系统&quot;不严谨——他们实际指 &quot;高可用 CP&quot; 而非真正不要 P。</p><hr><h2 id="三、pacelc-abadi-2010" tabindex="-1">三、PACELC (Abadi 2010) <a class="header-anchor" href="#三、pacelc-abadi-2010" aria-label="Permalink to &quot;三、PACELC (Abadi 2010)&quot;">​</a></h2><h3 id="公式" tabindex="-1">公式 <a class="header-anchor" href="#公式" aria-label="Permalink to &quot;公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (P) then {A vs C}</span></span>
<span class="line"><span>else       {L vs C}</span></span></code></pre></div><p>即使无分区时 (Normal case), 系统仍需在 <strong>延迟 (L)</strong> 与 <strong>一致性 (C)</strong> 间选——更高一致性通常需要更多确认、跨节点的延迟。</p><h3 id="系统分类" tabindex="-1">系统分类 <a class="header-anchor" href="#系统分类" aria-label="Permalink to &quot;系统分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>else (无分区)</th><th>then (分区)</th></tr></thead><tbody><tr><td>Cassandra</td><td>latency-priority (LOCAL_ONE 等)</td><td>availability-priority</td></tr><tr><td>Spanner</td><td>consistency-priority (TrueTime 保证)</td><td>consistency-priority</td></tr><tr><td>DynamoDB RC</td><td>latency-priority</td><td>availability-priority</td></tr><tr><td>DynamoDB StrongRead</td><td>consistency-priority</td><td>consistency-priority</td></tr><tr><td>MongoDB</td><td>consistency-priority (write concern=majority)</td><td>consistency-priority (writes 阻塞)</td></tr><tr><td>Riak</td><td>latency + tunable</td><td>availability-priority</td></tr><tr><td>PNUTs (Yahoo)</td><td>consistency-priority (write master)</td><td>consistency-priority</td></tr></tbody></table><h3 id="工程含义" tabindex="-1">工程含义 <a class="header-anchor" href="#工程含义" aria-label="Permalink to &quot;工程含义&quot;">​</a></h3><p>SLA: Amazon 对 DynamoDB 写承诺 P99 &lt; 10ms——要满足这条, 写入必须<strong>不强同步 quorum 全确认</strong>, 故放弃 strong consistency。Spanner P99 write ~100-200ms 跨数据中心——Google 同意付这延迟, 换取 linearizability。</p><h3 id="为什么-cap-三选二-是误读" tabindex="-1">为什么 CAP &quot;三选二&quot;是误读？ <a class="header-anchor" href="#为什么-cap-三选二-是误读" aria-label="Permalink to &quot;为什么 CAP &quot;三选二&quot;是误读？&quot;">​</a></h3><p>PACELC 更精确:</p><ul><li>&quot;三选二&quot; 把 else-then 全混在一起。</li><li>实际工程系统是<strong>双维度</strong>: 平常常 L vs C, 分区时 A vs C。CAP 只描述后者。</li></ul><hr><h2 id="四、base-basically-available-soft-state-eventually-consistent" tabindex="-1">四、BASE (Basically Available / Soft State / Eventually Consistent) <a class="header-anchor" href="#四、base-basically-available-soft-state-eventually-consistent" aria-label="Permalink to &quot;四、BASE (Basically Available / Soft State / Eventually Consistent)&quot;">​</a></h2><p>Pritchett 2008 eBay 提出。BASE 是 ACID 反面:</p><table tabindex="0"><thead><tr><th>ACID</th><th>BASE</th></tr></thead><tbody><tr><td>Atomic (原子)</td><td>Basically Available (基本可用)</td></tr><tr><td>Consistent (一致)</td><td>Soft State (软状态)</td></tr><tr><td>Isolated (隔离)</td><td>Eventually Consistent (最终一致)</td></tr><tr><td>Durable (持久)</td><td>—</td></tr></tbody></table><p>BASE 工程方法:</p><ol><li><strong>Compensating Transaction</strong>: 业务层补偿不 XA。如电商扣库存失败、后续 saga 回滚之前的支付。</li><li><strong>Saga Pattern</strong>: 长事务拆成 N 步、每步带补偿函数; 失败时反向 undo 各步。</li><li><strong>Idempotency</strong>: 所有 retry 必须幂等。eventId 去重, payment id client-generated。</li><li><strong>Eventually Consistent</strong>: 接受 inconsistency window, 用 task queue + retry 收敛。</li><li><strong>Read Repair</strong>: 读时发现不一致就此修复。</li></ol><h3 id="与-cap-关系" tabindex="-1">与 CAP 关系 <a class="header-anchor" href="#与-cap-关系" aria-label="Permalink to &quot;与 CAP 关系&quot;">​</a></h3><p>BASE 大多对 AP 系统而言。 BASE 系统不放弃可用性, 牺牲一致性 → AP+ELC。 但 Spanner 这种 CP+EC 的工程 BASE 就不用——Spanner 是 ACID-distributed 的事务路线, 严格 linearizable。</p><hr><h2 id="五、常见误读清单" tabindex="-1">五、常见误读清单 <a class="header-anchor" href="#五、常见误读清单" aria-label="Permalink to &quot;五、常见误读清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误读</th><th>纠正</th></tr></thead><tbody><tr><td>&quot;CP 系统永远不可用&quot;</td><td>只在分区时阻塞, 平常是 5 个 9 可用性</td></tr><tr><td>&quot;AP 系统永远不一致&quot;</td><td>分区结束后会收敛, eventually 一致</td></tr><tr><td>&quot;三选二&quot; (CA, CP, AP)</td><td>P 必选, 实际只有 CP vs AP; 更完整是 PACELC</td></tr><tr><td>&quot;MongoDB 是 CP&quot;</td><td>取决于 write concern — w=1 时基本 AP, w=majority 时 CP</td></tr><tr><td>&quot;Spanner 是 CA 因为是强一致&quot;</td><td>仍然 P- tolerant, 是 CP+EC, 跨数据中心分区时暂停写</td></tr><tr><td>&quot;CAP 是 100% 教科书定理&quot;</td><td>实际证明确立前提是异步网络, 同步网络可绕开 (practical 同步不存在)</td></tr><tr><td>&quot;BASE = 最终一致 就行&quot;</td><td>BASE 还要 idempotent retry + compensating + 业务级 invariant 维护</td></tr></tbody></table><hr><h2 id="六、易错清单" tabindex="-1">六、易错清单 <a class="header-anchor" href="#六、易错清单" aria-label="Permalink to &quot;六、易错清单&quot;">​</a></h2><ol><li><strong>CAP 中 C 不是 transactional consistency</strong>。它是 linearizability (单对象强一致)。 提到&quot;CP+ 事务&quot;是另一层 (linearizable + serializable)。</li><li><strong>PACELC 中 else 是&quot;常态&quot;、then 是&quot;分区&quot;</strong>: <ul><li>文章常错写 &quot;在 P 后选 A or C, 否则普通工作&quot;。 实际 else 描述的是平常也要选 L 或 C。</li></ul></li><li><strong>CAP Availability ≠ 高可用性定义</strong>: 形式化 A 是&quot;每个请求都有响应&quot;, 不是&quot;5 个 9 上线率&quot;; 后者更宽, 可以容忍 leader election 期间 1-2 秒不可用, 前者需要&quot;任意时刻有响应&quot;。</li><li><strong>partition tolerance 不是&quot;网络分区扛住无停机&quot;, 实际是&quot;网络分区时仍能维持 promise&quot;</strong>: partition 时当然会 loss 一些功能, 但<strong>不能协议错乱</strong>。 CP 系统在此正确&quot;宁可停写不可二心&quot;。</li><li><strong>Brewer 反思</strong>: 2017 Brewer 自己写 &quot;CAP 十二年&quot; 撤回&quot;三选二&quot; 提法, 提倡 PACELC。</li></ol><hr><h2 id="七、这一章带走的东西" tabindex="-1">七、这一章带走的东西 <a class="header-anchor" href="#七、这一章带走的东西" aria-label="Permalink to &quot;七、这一章带走的东西&quot;">​</a></h2><ol><li>CAP 是 <strong>asynchronous + 总能完成</strong> 假设下的定理, 真实系统都放宽 (eventual completion);</li><li>CP 不是&quot;always available minus partition&quot;; 是&quot;分区时牺牲可用性、让一致性 promise 保护数据&quot;。</li><li>PACELC 把&quot;常态也要选 L vs C&quot;加进来, 完整画像就清晰。</li><li>BASE 是 AP 系统工程模式: idempotency、补偿事务、saga、eventual consistency。</li><li>业务层根据场景选 CP vs AP: <ul><li>银行 = CP, component 牺牲延迟换 strict 强一;</li><li>shopping cart 消息、日志 = AP, 用户体验优先。</li></ul></li><li>Tunable consistency (Cassandra、Riak) 是后 CAP 时代的和解——让调用者决策, 而非系统专制。</li></ol><hr><p>下一节 → <a href="./ordering">一致性、线性化与序</a></p>`,57)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
